mapper.select:
SELECT COALESCE(SUM(amount), 0) FROM fin_netting
WHERE customer_idsupplier_id = #{partnerId}
  AND netting_date < #{date}

mapper.sql:
SELECT s.partner_id, COALESCE(c.code, sp.code) AS partner_code, COALESCE(c.name, sp.name) AS partner_name, u.nickname AS owner_name, s.opening, s.bill_balance, 0 - s.advance AS advance_balance, s.bad_debt, s.discount, 0 - s.linked_ap AS linked_ap,
ls.id AS linked_supplier_id, CONCAT(ls.code, ' ', ls.name) AS linked_supplier_name, NULL AS linked_supplier_id, NULL AS linked_supplier_name,
s.opening + s.bill_balance - s.advance - s.linked_ap AS net FROM ( SELECT x.partner_id, SUM(x.opening) AS opening, SUM(x.bill_balance) AS bill_balance, SUM(x.advance) AS advance, SUM(x.bad_debt) AS bad_debt, SUM(x.discount) AS discount, SUM(x.linked_ap) AS linked_ap FROM ( SELECT b.partner_id, CASE WHEN b.source_type = 'MANUAL' THEN b.amount - b.settled_amount ELSE 0 END AS opening, CASE WHEN b.source_type = 'MANUAL' THEN 0 ELSE b.amount - b.settled_amount END AS bill_balance, 0 AS advance, b.bad_debt_amount AS bad_debt, b.discount_amount AS discount, 0 AS linked_ap FROM fin_bill b WHERE b.kind = #{q.kind} AND b.partner_id = #{q.partnerId} UNION ALL SELECT a.partner_id, 0, 0, a.amount - a.used_amount, 0, 0, 0 FROM fin_advance a WHERE a.kind = #{settleKind} AND a.used_amount <> a.amount AND a.partner_id = #{q.partnerId}
UNION ALL SELECT lsb.customer_id, 0, 0, 0, 0, 0, b.amount - b.settled_amount FROM fin_bill b JOIN scm_supplier lsb ON lsb.id = b.partner_id WHERE b.kind = 'AP' AND lsb.customer_id IS NOT NULL AND lsb.customer_id = #{q.partnerId} UNION ALL SELECT lsa.customer_id, 0, 0, 0, 0, 0, 0 - (a.amount - a.used_amount) FROM fin_advance a JOIN scm_supplier lsa ON lsa.id = a.partner_id WHERE a.kind = 'PAYMENT' AND a.used_amount <> a.amount AND lsa.customer_id IS NOT NULL AND lsa.customer_id = #{q.partnerId}
) x GROUP BY x.partner_id ) s LEFT JOIN scm_customer c ON #{q.kind} = 'AR' AND c.id = s.partner_id LEFT JOIN scm_supplier sp ON #{q.kind} = 'AP' AND sp.id = s.partner_id LEFT JOIN scm_supplier ls ON ls.customer_id = s.partner_id LEFT JOIN sys_user u ON u.id = c.owner_id WHERE 1 = 1
AND (c.code LIKE CONCAT('%', #{q.keyword}, '%') OR c.name LIKE CONCAT('%', #{q.keyword}, '%') OR sp.code LIKE CONCAT('%', #{q.keyword}, '%') OR sp.name LIKE CONCAT('%', #{q.keyword}, '%'))
AND c.owner_id = #{q.ownerId} AND (s.opening <> 0 OR s.bill_balance <> 0 OR s.advance <> 0 OR s.linked_ap <> 0)
